class ActorEntry(SomNode):
    """An actor entry.
    
    Comprehensive actor definition following UML and Cockburn conventions.
    """
    def __init__(self, doc, path):
        super().__init__(doc, path)

    # Actor identification.
    @property
    def identification(self):
        return ActorIdentification(self.doc, f"{self.path}/identification")

    # Actor characteristics.
    @property
    def characteristics(self):
        return ActorCharacteristics(self.doc, f"{self.path}/characteristics")

    # Actor goals (Cockburn style).
    @property
    def goals(self):
        return SomList(self.doc, f"{self.path}/ACGO-GOAL-LST", lambda d, p: ActorGoals(d, p))

    # Actor permissions and access.
    @property
    def permissions(self):
        return SomList(self.doc, f"{self.path}/ACPE-PERM-LST", lambda d, p: ActorPermissions(d, p))

    # Actor technology profile.
    @property
    def technology(self):
        return ActorTechnologyProfile(self.doc, f"{self.path}/technology")

    # Actor interactions summary.
    @property
    def interactions(self):
        return ActorInteractionsSummary(self.doc, f"{self.path}/interactions")

