class RiskEntry(SomNode):
    """A risk entry (form).
    
    Comprehensive risk documentation following ISO 31000 and PMBOK guidelines.
    Captures risk identification, analysis, response planning, ownership,
    and monitoring information for systematic risk management.
    """
    def __init__(self, doc, path):
        super().__init__(doc, path)

    # Risk identification — unique identifier and basic description.
    @property
    def identification(self):
        return RiskIdentification(self.doc, f"{self.path}/identification")

    # Risk analysis — probability, impact, and scoring.
    @property
    def analysis(self):
        return RiskAnalysis(self.doc, f"{self.path}/analysis")

    # Risk response — strategy and planned actions.
    @property
    def response(self):
        return RiskResponse(self.doc, f"{self.path}/response")

    # Risk ownership and governance.
    @property
    def ownership(self):
        return RiskOwnership(self.doc, f"{self.path}/ownership")

    # Risk monitoring and tracking details.
    @property
    def monitoring(self):
        return RiskMonitoring(self.doc, f"{self.path}/monitoring")

    # Business impact assessment.
    @property
    def businessImpact(self):
        return RiskBusinessImpact(self.doc, f"{self.path}/businessImpact")

    # Relationships to other risks, assumptions, and project elements.
    @property
    def relationships(self):
        return SomList(self.doc, f"{self.path}/RIRE1-RELA-LST", lambda d, p: RiskRelationships(d, p))

